                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.OMNI_ORDER_PROCESSING_META AS with orders as ( select id, REPLACE(channel_order_id,\',\',\'\') as channel_order_id, REPLACE(channel_order_number,\',\',\'\') as channel_order_number, branch_code, order_status, DATEADD(minute, 330, nullif(created_at,\'\')) as created_at, DATEADD(minute, 330, nullif(cancelled_at,\'\')) as cancelled_at, cancelled_by, cancelled_reason, DATEADD(minute, 330, nullif(pick_list_created_at,\'\')) AS pick_list_created_at, DATEADD(minute, 330, nullif(pick_list_completed,\'\')) as pick_list_completed, DATEADD(minute, 330, nullif( packed_at,\'\')) as packed_at, DATEADD(minute, 330, nullif( manifested_at,\'\')) as manifested_at, DATEADD(minute, 330, nullif( dispatched_at,\'\')) as dispatched_at, DATEADD(minute, 330, nullif(tat,\'\')) as TAT , sku, picklist_no, manifest_no, location, quantity, reference_number, NULLIF(awb,\'\') as awb, cp_id, found, scanned_count, qc_done, payment_mode, total_price, wallet_used, price, cod_charge, coins_used, hsn_code, channel, cp_name, product_name, UPPER(product_type) as CATEGORY, shipping_city, shipping_state, shipping_pincode, customer_email, customer_phone, billing_address, channel_user_id, shipping_address, allocation_rule_id, channel_product_id, logic_order_create, logic_reference_id, shopify_fulfillment_status, is_quick_com, drop_lat, drop_lon, pickup_lat, pickup_lon from snitch_db.maplemonk.s3_s3_order_processing ), store_mapping as ( select store_name, store_code, CASE WHEN lower(region) like \'%ben%\' or lower(region) like \'%ban%\' then \'BANGALORE\' else region end as region, Cluster from snitch_db.maplemonk.OFFLINE_STORE_DETAILED_MAPPING where store_code != 0 ), draft1 as ( select d.store_name, d.region, d.cluster, o.* from orders o left join store_mapping d on o.branch_code = d.store_code ), cp1 as ( select awb_number, assigned_date, pickup_date as handover_date, delivery_date, latest_timestamp, latest_remark , status, order_id, courier_partner, outfordelivery_date, out_for_delivery_attempts, max_sla, min_sla, edd_cp, payment_method, pincode, mapped_city, mapped_state, final_zone, rto_mark_date, failed_del_reason, last_failed_del_reason, mode_1, warehouse from snitch_db.maplemonk.cp_1 where lower(mode) = \'forward\' and assigned_date::DATE >= \'2025-05-01\' ), uc as ( select order_name, sku as uc_sku, awb as uc_awb, warehouse_name, sla_status, item_status, packed_time, dispatched_timestamp, saleorderitemcode from snitch_db.maplemonk.warehouse_sla_performance where marketplace_mapped = \'SHOPIFY\' and uc_created >= \'2025-05-01\' ) , d2 as ( select *, coalesce(d.awb,u.uc_awb) as awb_dummy from draft1 d left join uc u on concat(d. channel_order_number,d.sku) = concat(u.order_name,u.uc_sku) ), final2 as ( select case when warehouse_name != \'Surat-VRMall\' THEN 1 else 0 end as FACILITY_SWITCH, * from d2 d left join cp1 c on d.awb_dummy = c.awb_number ) select * from final2",
